package main

import (
	"encoding/json"
	"flag"
	"fmt"
	"os"
	"strconv"
)

func main() {
	if len(os.Args) < 2 {
		printErrorAndExit("no command provided", 42)
	}

	switch os.Args[1] {
	case "add":
		addCmd := flag.NewFlagSet("add", flag.ExitOnError)
		description := addCmd.String("description", "", "Description of the task")
		addCmd.Parse(os.Args[2:])

		if *description == "" {
			printErrorAndExit("invalid arguments", 42)
		}

		tasks, err := LoadTasks()
		if err != nil {
			printErrorAndExit(fmt.Sprintf("could not load tasks: %v", err), 1)
		}

		nextID := 1
		if len(tasks) > 0 {
			nextID = tasks[len(tasks)-1].ID + 1
		}

		newTask := Task{
			ID:          nextID,
			Description: *description,
			Done:        false,
		}

		tasks = append(tasks, newTask)

		err = SaveTasks(tasks)
		if err != nil {
			printErrorAndExit(fmt.Sprintf("could not save tasks: %v", err), 1)
		}

		response := map[string]interface{}{"id": newTask.ID, "status": "added"}
		jsonResponse, _ := json.Marshal(response)
		fmt.Println(string(jsonResponse))

	case "list":
		listCmd := flag.NewFlagSet("list", flag.ExitOnError)
		listCmd.Parse(os.Args[2:])

		tasks, err := LoadTasks()
		if err != nil {
			printErrorAndExit(fmt.Sprintf("could not load tasks: %v", err), 1)
		}

		var pendingTasks []Task
		for _, task := range tasks {
			if !task.Done {
				pendingTasks = append(pendingTasks, task)
			}
		}

		jsonResponse, _ := json.Marshal(pendingTasks)
		fmt.Println(string(jsonResponse))

	case "done":
		doneCmd := flag.NewFlagSet("done", flag.ExitOnError)
		idStr := ""
		if len(os.Args) > 2 {
			idStr = os.Args[2]
		}
		doneCmd.Parse(os.Args[2:])

		id, err := strconv.Atoi(idStr)
		if err != nil || id <= 0 {
			printErrorAndExit("invalid arguments", 42)
		}

		tasks, err := LoadTasks()
		if err != nil {
			printErrorAndExit(fmt.Sprintf("could not load tasks: %v", err), 1)
		}

		found := false
		for i := range tasks {
			if tasks[i].ID == id {
				tasks[i].Done = true
				found = true
				break
			}
		}

		if !found {
			printErrorAndExit(fmt.Sprintf("task with ID %d not found", id), 42)
		}

		err = SaveTasks(tasks)
		if err != nil {
			printErrorAndExit(fmt.Sprintf("could not save tasks: %v", err), 1)
		}

		response := map[string]interface{}{"id": id, "status": "completed"}
		jsonResponse, _ := json.Marshal(response)
		fmt.Println(string(jsonResponse))

	default:
		printErrorAndExit("unknown command", 42)
	}
}

func printErrorAndExit(message string, code int) {
	output, _ := json.Marshal(map[string]string{"error": message})
	fmt.Println(string(output))
	os.Exit(code)
}

package main

import (
	"bytes"
	"encoding/json"
	"io/ioutil"
	"os"
	"strconv"
	"strings"
	"testing"
)

const testTasksFile = "test_tasks.json"

// setupTestEnvironment sets up a clean test environment by creating a dummy tasks file.
func setupTestEnvironment() {
	os.Remove(testTasksFile) // Ensure no old file exists
	tasksFile = testTasksFile // Redirect to test file
}

// teardownTestEnvironment cleans up the test environment.
func teardownTestEnvironment() {
	os.Remove(testTasksFile)
	tasksFile = "tasks.json" // Reset to original
}

// captureOutput captures stdout and stderr.
func captureOutput(f func()) (string, string) {
	oldStdout := os.Stdout
	oldStderr := os.Stderr

r, w, _ := os.Pipe()
	os.Stdout = w
	os.Stderr = w // Redirect stderr to also capture

	f()

	w.Close()

out, _ := ioutil.ReadAll(r)

os.Stdout = oldStdout
	os.Stderr = oldStderr

	return string(out), string(out) // Return both as string, since stderr is redirected to stdout
}

func TestLoadAndSaveTasks(t *testing.T) {
	setupTestEnvironment()
	defer teardownTestEnvironment()

	// Test saving and loading empty list
	emptyTasks := []Task{}
	err := SaveTasks(emptyTasks)
	if err != nil {
		t.Fatalf("SaveTasks failed for empty list: %v", err)
	}

	loadedTasks, err := LoadTasks()
	if err != nil {
		t.Fatalf("LoadTasks failed for empty list: %v", err)
	}
	if len(loadedTasks) != 0 {
		t.Errorf("Expected 0 tasks, got %d", len(loadedTasks))
	}

	// Test saving and loading tasks
	tasks := []Task{
		{ID: 1, Description: "Task 1", Done: false},
		{ID: 2, Description: "Task 2", Done: true},
	}
	err = SaveTasks(tasks)
	if err != nil {
		t.Fatalf("SaveTasks failed: %v", err)
	}

	loadedTasks, err = LoadTasks()
	if err != nil {
		t.Fatalf("LoadTasks failed: %v", err)
	}
	if len(loadedTasks) != 2 {
		t.Errorf("Expected 2 tasks, got %d", len(loadedTasks))
	}
	if loadedTasks[0].ID != 1 || loadedTasks[1].ID != 2 {
		t.Errorf("Loaded tasks do not match expected IDs")
	}
}

func TestAddCommand(t *testing.T) {
	setupTestEnvironment()
	defer teardownTestEnvironment()

	// Test adding a single task
	os.Args = []string{"cmd", "add", "-description", "Buy milk"}
	out, _ := captureOutput(main)

	expected := `{"id":1,"status":"added"}\n`
	if out != expected {
		t.Errorf("Expected %q, got %q", expected, out)
	}

	// Verify task is saved
	tasks, _ := LoadTasks()
	if len(tasks) != 1 || tasks[0].Description != "Buy milk" || tasks[0].ID != 1 {
		t.Errorf("Task not saved correctly: %+v", tasks)
	}

	// Test adding another task, checking ID generation
	os.Args = []string{"cmd", "add", "-description", "Do laundry"}
	out, _ = captureOutput(main)

	expected = `{"id":2,"status":"added"}\n`
	if out != expected {
		t.Errorf("Expected %q, got %q", expected, out)
	}

	tasks, _ = LoadTasks()
	if len(tasks) != 2 || tasks[1].Description != "Do laundry" || tasks[1].ID != 2 {
		t.Errorf("Second task not saved correctly: %+v", tasks)
	}

	// Test invalid arguments (missing description)
	os.Args = []string{"cmd", "add", "-description", ""}
	exitCode := 0
	mainFunc := func() {
		defer func() {
			if r := recover(); r != nil {
				if e, ok := r.(int); ok {
					exitCode = e
				}
			}
		}()
		oldExit := os.Exit
		defer func() { os.Exit = oldExit }()
		os.Exit = func(code int) {
			panic(code)
		}
		main()
	}
	out, _ = captureOutput(mainFunc)

	expected = `{"error":"invalid arguments"}\n`
	if out != expected || exitCode != 42 {
		t.Errorf("Expected %q with exit code 42, got %q with exit code %d", expected, out, exitCode)
	}
}

func TestListCommand(t *testing.T) {
	setupTestEnvironment()
	defer teardownTestEnvironment()

	// Test listing empty tasks
	os.Args = []string{"cmd", "list"}
	out, _ := captureOutput(main)
	expected := `[]\n`
	if out != expected {
		t.Errorf("Expected %q, got %q", expected, out)
	}

	// Add some tasks
