		{ID: 1, Description: "Task 1", Done: false},
		{ID: 2, Description: "Task 2", Done: true},
		{ID: 3, Description: "Task 3", Done: false},
	})

	// Test listing pending tasks
	os.Args = []string{"cmd", "list"}
	out, _ = captureOutput(main)
	expected = `[{"id":1,"description":"Task 1","done":false},{"id":3,"description":"Task 3","done":false}]\n`
	if out != expected {
		t.Errorf("Expected %q, got %q", expected, out)
	}
}

