func TestUnknownCommand(t *testing.T) {
	setupTestEnvironment()
	defer teardownTestEnvironment()

	os.Args = []string{"cmd", "foobar"}
	exitCode := 0
	mainFunc := func() {
		defer func() {
			if r := recover(); r != nil {
				if e, ok := r.(int); ok {
					exitCode = e
