// setupTestEnvironment sets up a clean test environment by creating a dummy tasks file.
func setupTestEnvironment(t *testing.T) {
	os.Remove(testTasksFile) // Ensure no old file exists
	tasksFile = testTasksFile // Redirect to test file

	// Store original exit and replace for testing
	originalExit := exit
	exit = func(code int) {
		capturedExitCode = code
		panic("os.Exit was called") // Use panic to stop execution without actually exiting
	}
	t.Cleanup(func() { // Use t.Cleanup for proper teardown
		exit = originalExit // Restore original exit function
		tasksFile = "tasks.json" // Reset to original
		capturedExitCode = 0     // Reset captured exit code
	})
}

