	os.Stdout = w
	os.Stderr = w // Redirect stderr to also capture

	// Reset capturedExitCode before each test that uses it
	capturedExitCode = 0

	// Run the function that might call main.exit and panic
	func() {
		defer func() {
			if r := recover(); r != nil {
				// We expect a panic from our test `exit` function, ignore it
				if r != "os.Exit was called" {
					panic(r) // Re-panic if it's not our expected panic
				}
