package main

import (
	"io/ioutil"
	"os"
	"testing"
)

const testTasksFile = "test_tasks.json"

var capturedExitCode int

// setupTestEnvironment sets up a clean test environment by creating a dummy tasks file.
func setupTestEnvironment(t *testing.T) {
	os.Remove(testTasksFile) // Ensure no old file exists
	tasksFile = testTasksFile // Redirect to test file

	// Store original exit and replace for testing
	originalExit := exit
	exit = func(code int) {
		capturedExitCode = code
		panic("os.Exit was called") // Use panic to stop execution without actually exiting
	}
	t.Cleanup(func() { // Use t.Cleanup for proper teardown
		exit = originalExit // Restore original exit function
		tasksFile = "tasks.json" // Reset to original
		capturedExitCode = 0     // Reset captured exit code
	})
}

// captureOutput captures stdout and stderr.
func captureOutput(f func()) (string, string) {
	oldStdout := os.Stdout
	oldStderr := os.Stderr

	r, w, _ := os.Pipe()
	os.Stdout = w
	os.Stderr = w // Redirect stderr to also capture

	// Reset capturedExitCode before each test that uses it
	capturedExitCode = 0

	// Run the function that might call main.exit and panic
	func() {
		defer func() {
			if r := recover(); r != nil {
				// We expect a panic from our test `exit` function, ignore it
				if r != "os.Exit was called" {
					panic(r) // Re-panic if it's not our expected panic
				}
			}
		}()
		f()
	}()

	w.Close()

	out, _ := ioutil.ReadAll(r)

	os.Stdout = oldStdout
	os.Stderr = oldStderr

	return string(out), string(out) // Return both as string, since stderr is redirected to stdout
}

