	if len(data) == 0 {
		return []Task{}
	}

	var tasks []Task
	err = json.Unmarshal(data, &tasks)
	if err != nil {
		t.Fatalf("Error unmarshalling tasks from %s: %v", filePath, err)
	}

	return tasks
}

